}

resource sqlDatabase ''Microsoft.Sql/servers/databases@2023-05-01-preview'' = {
  parent: sqlServer
  name: ''${appName}-db''
  location: location
  sku: {
    name: ''GP_S_Gen5_2''
    tier: ''GeneralPurpose''
  }
  properties: {
    autoPauseDelay: 60
