','.claude\skills\board\SKILL.md','075f9ea26d91a367f7729e6b9a17c75a4542ac6af5d092dc9efa12c8f91dbd87','skill,simplicio,coding',1.3);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('skill:simplicio-runtime:board-minutes','project_skill','skill://simplicio-runtime/board-minutes','skill: board-minutes','---
name: board-minutes
description: >
  Drafts board or committee meeting minutes in your house format. Auto-detects
  upcoming board and committee meetings from your calendar, asks for the agenda
  and any slides or pre-read materials, and produces a complete draft in the
  format learned from your seed minutes. Also handles written consents in lieu
  of meetings. Trigger: "board minutes", "draft minutes", "upcoming board
